INSERT INTO "paginas_versiones" ("id", "pagina_id", "contenido", "layout", "numero_version", "estado", "motivo_rechazo", "revisor_id", "publicado_por", "publicado_en", "creado_en", "creado_por", "revisado_en", "comentario_cambios") VALUES
  ($olo$4b11398a-3299-4dd1-ab96-ffda3fad7678$olo$, $olo$13bcd88c-01c4-4f95-a218-48108c126a06$olo$, $olo${"root":{"props":{}},"zones":{},"content":[{"type":"MatrizBanner","props":{"id":"matriz-banner","titulo":"Matriz de \n**PERTINENCIA**","imagenAlt":"Matriz de Pertinencia","imagenSrc":"/assets/img/BannerOficial.png"}},{"type":"TextoRico","props":{"id":"matriz-que-es","ancho":"estrecho","fondo":"gris","titulo":"¿Qué es?","contenido":"<p>La Matriz de Pertinencia es una herramienta estratégica del SENA, que permite a través de sus 5 variables:</p><ol><li>vinculación laboral.</li><li>tendencia de las ocupaciones.</li><li>demanda social de los programas de oferta titulada.</li><li>sector estratégico de los programas de formación.</li><li>contrato de aprendizaje; comprender que tan bien se ajustan los programas ofrecidos por los centros de formación a la realidad del mercado laboral colombiano.</li></ol>"}},{"type":"ImagenDestacada","props":{"id":"matriz-sabias-que","ancho":"contenido","fondo":"blanco","titulo":"","imagenAlt":"Sabías que... La Matriz ofrece información desde 2011","imagenSrc":"/assets/img/matriz-1.png"}},{"type":"SeccionCarrusel","props":{"id":"matriz-carrusel","fondo":"blanco","titulo":"","autoplay":true,"imagenes":[{"alt":"Matriz de Pertinencia 1","src":"/assets/img/Carrusel1.png"},{"alt":"Matriz de Pertinencia 2","src":"/assets/img/Carrusel2.png"},{"alt":"Matriz de Pertinencia 3","src":"/assets/img/Carrusel3.png"},{"alt":"Matriz de Pertinencia 4","src":"/assets/img/Carrusel4.png"},{"alt":"Matriz de Pertinencia 5","src":"/assets/img/Carrusel5.png"},{"alt":"Matriz de Pertinencia 6","src":"/assets/img/Carrusel6.png"}],"disposicion":"columna","mostrarBotones":true,"imagenesPorPagina":3}},{"type":"TasaVideo","props":{"id":"matriz-video","videoUrl":"https://www.youtube.com/embed/4E7Sci4DAVQ","descargaUrl":"","tituloInicio":"¿Ya sabes como acceder a la matriz de pertinencia en","descargaTexto":"","tituloDestacado":"«CompromISO»?","descargaEtiqueta":"Descargar"}},{"type":"TasaDashboards","props":{"id":"matriz-tableros","tableros":[{"titulo":"Dashboard OLO - Matriz","urlPowerBi":"https://app.powerbi.com/view?r=eyJrIjoiMWIxNWMwYjItNzdhZS00ZGE1LWExMDktYzZhOTgwNjZkNTZmIiwidCI6ImNiYzJjMzgxLTJmMmUtNGQ5My05MWQxLTUwNmM5MzE2YWNlNyIsImMiOjR9&pageName=ReportSection14c82e0795ad03436073","descripcion":"Resultados de vinculación laboral formal (titulada), con una periodicidad semestral. Genera un indicador de vinculación donde se relaciona el número de vinculados laboralmente en el mercado formal y el total de egresados, para un grupo de seguimiento particular."}]}},{"type":"DescargasConPresentacion","props":{"id":"matriz-descargas","titulo":"**Descargas**","enlaces":[{"url":"","etiqueta":"Matriz de pertinencia 2025"},{"url":"","etiqueta":"Matriz de pertinencia 2024"}],"archivoUrl":"/uploads/documents/Presentación1.pptx"}}]}$olo$::jsonb, NULL, 1, $olo$publicado$olo$, NULL, NULL, NULL, '2026-10-23T20:01:36.649Z', '2026-10-23T20:01:35.947Z', NULL, NULL, $olo$Versión inicial$olo$),
  ($olo$23394659-cc39-4b23-b3f4-72b23626db16$olo$, $olo$20701c2c-c615-47e5-9323-cc0eab250941$olo$, $olo${"root":{"props":{}},"zones":{},"content":[{"type":"EncuestaBanner","props":{"id":"calidad-banner","titulo":"CALIDAD DE LA FORMACIÓN","imagenAlt":"Ilustración Calidad de la Formación","imagenSrc":"/assets/img/banner-seguimiento-laboral.png","antetitulo":"Encuesta de"}},{"type":"TextoConImagen","props":{"id":"calidad-objetivo","fondo":"gris","titulo":"¿Cuál es el **objetivo**?","contenido":"<p>El objetivo principal es <strong>evaluar la percepción de los empresarios sobre la contribución de los aprendices en sus organizaciones.</strong></p><h3>Puntos Específicos:</h3><ul><li>Conocer las perspectivas de los empresarios frente al <strong>rol de los aprendices</strong> en sus labores.</li><li>Valorar los conocimientos y habilidades <strong>de los aprendices en un contexto laboral real.</strong></li><li><strong>Ofrecer información</strong> sobre la <strong>pertinencia de la formación</strong> de los aprendices respecto a las demandas del mercado laboral.</li><li>Evaluar la disposición de los empresarios a <strong>contratar aprendices</strong> una vez finalizado su periodo de formación.</li></ul><h3><em>¿Qué encontrarás aquí?</em></h3><ul><li>Una <strong>explicación detallada de la metodología de la encuesta</strong> realizada.</li><li>Los <strong>principales resultados</strong> presentados de forma concisa y visual en una <strong>presentación.</strong></li><li>El <strong>conjunto de datos brutos</strong> para que pueda realizar su propia exploración y análisis a profundidad.</li></ul>","imagenAlt":"Resultado de encuesta - Mapa de disponibilidad a contratar","imagenSrc":"/assets/img/Resultado-de-encuesta.png","ladoImagen":"derecha","pieDeImagen":"Resultado de encuesta calidad de la Formación"}},{"type":"TasaVideo","props":{"id":"calidad-video","videoUrl":"https://www.youtube.com/embed/4E7Sci4DAVQ","descargaUrl":"/uploads/documents/Encuesta Calidad Formación datos.xlsx","tituloInicio":"Aquí te contamos todo sobre la","descargaTexto":"Descarga aquí los datos de la encuesta","tituloDestacado":"encuesta de calidad de la formación","descargaEtiqueta":"Descargar"}},{"type":"DescargasConPresentacion","props":{"id":"calidad-portal","titulo":"Página Web Observatorio Laboral","enlaces":[{"url":"","etiqueta":"Informes"},{"url":"","etiqueta":"Resultados"},{"url":"","etiqueta":"Boletines Tendencia"}],"archivoUrl":"/uploads/documents/Presentación1.pptx"}}]}$olo$::jsonb, NULL, 1, $olo$publicado$olo$, NULL, NULL, NULL, '2026-10-23T20:01:38.162Z', '2026-10-23T20:01:37.391Z', NULL, NULL, $olo$Versión inicial$olo$),
  ($olo$dc975a5e-5acf-46d9-b34b-f7596b1d4d43$olo$, $olo$21d945ab-78e1-46e4-a85d-dd7c5c48faf0$olo$, $olo${"root":{"props":{}},"zones":{},"content":[{"type":"PoliticaPrivacidadEncabezado","props":{"id":"politica-encabezado-static","intro":"<p>El <strong>Servicio Nacional de Aprendizaje SENA</strong>, a través del <strong>Observatorio Laboral y Ocupacional</strong>, dispone para consulta ciudadana los lineamientos oficiales de la Política de Seguridad y Privacidad de la Información y la Política de Tratamiento para Protección de Datos Personales, en estricto cumplimiento de la Ley Estatutaria 1581 de 2012 (Habeas Data) y el Sistema de Gestión CompromISO.</p><p>A continuación, seleccione el documento normativo que desea consultar para leerlo directamente en formato PDF o descargar una copia oficial.</p>","titulo":"Políticas de Seguridad, Privacidad y Tratamiento de Datos"}},{"type":"VisorDocumentosNormativos","props":{"id":"visor-documentos-static","titulo":"Documentos y Recursos Normativos Oficiales","documentos":[{"titulo":"Política de Seguridad y Privacidad de la Información","descripcion":"Documento oficial del Sistema Integrado de Gestión y Autocontrol CompromISO SENA. Lineamientos de seguridad digital y confidencialidad institucional.","documentoId":"6701","etiquetaTab":"1. Seguridad y Privacidad (ID: 6701)"},{"titulo":"Política de Tratamiento para Protección de Datos Personales","descripcion":"Régimen y garantías institucionales para el tratamiento, protección de datos personales y ejercicio de derechos de Habeas Data conforme a la Ley 1581 de 2012.","documentoId":"6914","etiquetaTab":"2. Tratamiento de Datos (ID: 6914)"}]}},{"type":"CanalesAtencion","props":{"id":"canales-atencion-static","intro":"<p>Para ejercer sus derechos de conocer, actualizar, rectificar o suprimir sus datos personales, o para presentar cualquier consulta o reclamo relativo a la protección de datos, el SENA pone a disposición los siguientes canales oficiales:</p>","titulo":"Canales de Atención y Ejercicio de Derechos (Habeas Data)","canales":[{"valor":"servicioalciudadano@sena.edu.co","etiqueta":"Correo Electrónico"},{"valor":"01 8000 910270 • (601) 343 0111","etiqueta":"Línea Gratuita Nacional"},{"valor":"Calle 57 No. 8 - 69, Bogotá D.C.","etiqueta":"Dirección General"},{"valor":"10 a 15 días hábiles (Ley 1581)","etiqueta":"Tiempos de Respuesta"}]}}]}$olo$::jsonb, NULL, 1, $olo$publicado$olo$, NULL, NULL, NULL, '2026-09-04T21:28:29.164Z', '2026-09-04T21:28:28.413Z', NULL, NULL, $olo$Versión inicial$olo$),
