  ($olo$c10aa380-17d2-47a5-9f92-0322b096a0cc$olo$, $olo$cd4c78c5-aeca-47a6-b22f-af1da4cc4d04$olo$, $olo${"root":{"props":{}},"zones":{},"content":[{"type":"EncuestaBanner","props":{"id":"seguimiento-banner","titulo":"SEGUIMIENTO LABORAL","imagenAlt":"Ilustración Seguimiento Laboral","imagenSrc":"/assets/img/banner-seguimiento-laboral.png","antetitulo":"Encuesta de","imagenDerecha":true}},{"type":"TextoRico","props":{"id":"seguimiento-objetivo","ancho":"ancho","fondo":"gris","titulo":"¿Cuál es el **objetivo**?","contenido":"<p>Conocer la transición de nuestros egresados después de su certificación y hacer seguimiento un año después a su proceso de vinculación al mercado laboral.</p><h3>Puntos Específicos:</h3><ul><li>Conocer las actividades en que se desempeñaron los egresados el último año.</li><li>Entender en que actividades productivas se encuentran laborando los egresados después de su certificación.</li><li>Saber como el aprendizaje impartido por el SENA ha contribuido a su vida e intereses en general.</li></ul><h3>¿Qué encontrarás aquí?</h3><ul><li>Una <strong>explicación detallada de la metodología de la encuesta</strong> realizada.</li><li>Los <strong>principales resultados</strong> presentados de forma concisa y visual en una <strong>presentación</strong>.</li><li>El <strong>conjunto de datos brutos</strong> para que pueda realizar su propia exploración y análisis a profundidad.</li></ul>"}},{"type":"ImagenDestacada","props":{"id":"seguimiento-resultados-1","ancho":"completo","fondo":"gris","titulo":"","imagenAlt":"Resultados de la encuesta de seguimiento laboral","imagenSrc":"/assets/img/encuesta-seguimiento.png"}},{"type":"ImagenDestacada","props":{"id":"seguimiento-resultados-2","ancho":"completo","fondo":"blanco","titulo":"","imagenAlt":"Más resultados de la encuesta de seguimiento laboral","imagenSrc":"/assets/img/encuesta-de-seguimiento-laboral-2.png"}},{"type":"TextoConImagen","props":{"id":"seguimiento-portal","fondo":"gris","titulo":"Portal de aprendizaje","contenido":"<ul><li>Orientación a los nuevos empleados.</li><li>Rendimiento y desarrollo.</li><li>Habilidades y aprendizaje.</li><li>Promociones.</li><li>Trabajos internos y referencias.</li><li>Herramientas y métodos.</li></ul>","imagenAlt":"","imagenSrc":"","archivoUrl":"/uploads/documents/Presentación1.pptx","ladoImagen":"derecha","pieDeImagen":""}}]}$olo$::jsonb, NULL, 1, $olo$publicado$olo$, NULL, NULL, NULL, '2026-10-23T20:01:39.610Z', '2026-10-23T20:01:38.907Z', NULL, NULL, $olo$Versión inicial$olo$)
